CREATE INDEX "orders_unserved_idx" ON "orders" USING btree ("merchant_id") WHERE "orders"."state" = 'unfulfilled' and (("orders"."record" -> 'order' -> 'dispatch' ->> 'accepted') = 'true' or ("orders"."record" -> 'order' -> 'closure' ->> 'cause') = 'merchant_refused' or (("orders"."record" -> 'order' -> 'closure' ->> 'cause') = 'deadline_expired' and ("orders"."record" -> 'order' -> 'timestamps' ->> 'dispatchedAt') is not null));